  const bondedCount = batches.filter(b => b.status === BatchStatus.BONDED || !b.dutyPaid).length;
  const integrityRate = totalBatches > 0 ? Math.round(((totalBatches - batches.filter(b => !b.integrityHash).length) / totalBatches) * 100) : 0;

